update public.lancamentos set resumo = 'Studios de 18 a 24 m² na Av. Rebouças, entre Jardins e Pinheiros, pensados para locação de curta e média duração com gestão da 360 Suítes.', destaques = 'Entre Jardins e Pinheiros, a 3 quadras da Estação Oscar Freire e a 350 m da Rua Oscar Freire
