update public.imobiliarias set situacao = 'parceira', ativa_no_hub = true where nome in ('Lanportus','Prospect Imobiliária','Sônia & Ramalho','Andreotti Negócios Imobiliários','Índice Imóveis');

insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Vici: “Posso morar no studio HIS-2?”', 'Se o cliente não está na faixa de renda HIS-2 (3 a 6 salários mínimos), ele compra como investidor e não pode morar. A unidade é destinada à locação tradicional para inquilino enquadrado durante 10 anos a partir do Habite-se. Depois disso, fica totalmente livre para venda e aluguel, inclusive por temporada.', 'vici', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Vici: “Posso usar FGTS ou colocar no Airbnb?”', 'Na compra como investidor HIS-2, o FGTS não pode ser usado e a locação por temporada fica proibida durante os 10 anos de restrição. O ganho está no preço: o m² com HIS sai por volta de R$ 13.200 contra R$ 22.000 no mercado livre da região, e essa diferença se realiza na liberação.', 'vici', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('apresentacao', 'Vici: tese em uma frase', '“Você compra hoje um studio a 4 minutos da Faria Lima pagando cerca de 40% menos que o mercado livre, recebe aluguel durante a restrição e, quando a unidade é liberada, captura a valorização da região.”', 'vici', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Verya: “Já posso fechar?”', 'O Verya está em pré-lançamento. O material é para estudo de mercado e a venda só acontece após o alvará e o registro do memorial de incorporação. O que dá para fazer agora é registrar o interesse do cliente para ele ter prioridade na escolha da unidade.', 'verya', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('apresentacao', 'Verya: rentabilidade em short stay', 'Com diária base de R$ 460 e gestão da 360 Suítes, os cenários projetados vão de R$ 5.540/mês (60% de ocupação) a R$ 9.050/mês (90%). A ocupação média da região fica entre 75% e 85%. Sempre apresente como projeção, não como garantia.', 'verya', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Rooftop: “Qual o preço?”', 'O Rooftop Perdizes ainda está em aprovação e não tem tabela divulgada. Registre o interesse do cliente e o perfil (família ou investidor) para avisá-lo assim que o lançamento for liberado.', 'rooftop', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('apresentacao', 'Full: para quem quer receber logo', 'O Full Jardim São Paulo tem entrega prevista para dezembro/2026, a mais próxima do portfólio. Para o investidor que quer começar a receber aluguel cedo, é o argumento principal.', 'full', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('apresentacao', 'Blue Park: para a família', 'Três dormitórios em frente a um parque e a 2 minutos do metrô, com gardens de até 87 m² e a possibilidade de unir unidades. Use com famílias que querem espaço sem sair de um bairro tradicional.', 'blue', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('apresentacao', 'Pina 1875: renda com gestão profissional', 'Studio a 3 quadras do Metrô Vila Madalena com gestão da 360 Suítes. No cenário realista, cerca de R$ 4.180/mês e 17,4% ao ano. A microrregião tem ocupação média de 92%.', 'pina', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('qualificacao', 'Qual projeto para qual cliente', 'Investidor que quer renda logo: Full Jardim São Paulo. Investidor de longo prazo com desconto de entrada: Vici Faria Lima (HIS-2). Renda com short stay: Pina 1875 e Verya. Família: Blue Park e Rooftop. Primeiro imóvel com bom custo: VIP Vila Prudente.', null, 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id;
update public.abordagens set texto = 'Pode ficar tranquilo: o atendimento pela imobiliária parceira tem as mesmas condições da Chaincorp, e eu acompanho todo o processo até a assinatura. Seu atendimento fica registrado comigo para você ter um ponto de contato só.' where titulo = '"Vou comprar direto com a construtora"';

-- Trilha 4 reescrita para o fluxo simplificado
do $$ declare t bigint; begin
  select id into t from public.trilhas where titulo in ('Nível 4 · Da ficha à minuta', 'Nível 4 · Do interesse ao fechamento') order by id limit 1;
  if t is null then return; end if;
  update public.trilhas set titulo = 'Nível 4 · Do interesse ao fechamento', descricao = 'Como registrar o negócio, organizar a documentação e contar com o coordenador até a assinatura.' where id = t;
  delete from public.quiz_perguntas where trilha_id = t;
  delete from public.aulas where trilha_id = t;
  insert into public.aulas (trilha_id, titulo, tipo, duracao_min, conteudo, ordem) values (t, 'Registre cada negócio na Academia', 'material', 4, 'Quando um cliente demonstrar interesse real, registre em Negócios: nome do cliente, projeto, unidade e valor. Atualize o status conforme a conversa avança: em negociação, proposta enviada, aprovada, vendida ou perdida.

O registro mostra para a Chaincorp quem está atendendo cada cliente e ajuda o seu coordenador a apoiar você na hora certa.', 1);
  insert into public.aulas (trilha_id, titulo, tipo, duracao_min, conteudo, ordem) values (t, 'Checklist documental', 'roteiro', 4, 'Para a proposta seguir, peça ao cliente de uma vez só:
· Cópia de RG e CPF
· Comprovante de residência atualizado
· Comprovante de rendimentos ou holerites
· Comprovante de TED ou Pix do sinal

Com os documentos em mãos, fale com o seu coordenador para enviar a proposta oficial da Chaincorp.', 2);
  insert into public.aulas (trilha_id, titulo, tipo, duracao_min, conteudo, ordem) values (t, 'O papel do coordenador de parcerias', 'leitura', 3, 'Você não está sozinho. O coordenador de parcerias da Chaincorp acompanha cada negócio da rede: tira dúvidas de produto, confirma tabela e disponibilidade, participa de reuniões com clientes quando necessário e conduz a proposta junto à Chaincorp até a assinatura.

Acione o coordenador sempre que o cliente estiver pronto para avançar.', 3);
  insert into public.quiz_perguntas (trilha_id, enunciado, opcoes, correta, explicacao, ordem) values (t, 'Quando registrar um negócio na Academia?', '["Só depois da venda", "Assim que o cliente demonstrar interesse real", "Nunca, é opcional", "Só se o gestor pedir"]'::jsonb, 1, 'Registrar cedo permite que o coordenador apoie o atendimento.', 1);
  insert into public.quiz_perguntas (trilha_id, enunciado, opcoes, correta, explicacao, ordem) values (t, 'Qual destes documentos faz parte do checklist?', '["Certidão de casamento", "Comprovante de TED ou Pix do sinal", "Declaração de IR de 5 anos", "Nenhum"]'::jsonb, 1, 'O comprovante do sinal é obrigatório.', 2);
  insert into public.quiz_perguntas (trilha_id, enunciado, opcoes, correta, explicacao, ordem) values (t, 'Quem conduz a proposta junto à Chaincorp?', '["O cliente", "O coordenador de parcerias, com o corretor", "A imobiliária sozinha", "O cartório"]'::jsonb, 1, 'O coordenador conduz a proposta com o corretor até a assinatura.', 3);
end $$;
update public.aulas set conteudo = replace(conteudo, 'Você acompanha em Minhas propostas, com atualização em tempo real.', 'Você acompanha o andamento em Negócios.') where conteudo like '%Minhas propostas%';
update public.aulas set conteudo = replace(replace(conteudo, '4. Com o cliente interessado, você preenche a Ficha Cadastral Oficial dentro do Hub.
5. A Mesa de Crédito da Chaincorp analisa a ficha e você acompanha cada etapa até a minuta.', '4. Com o cliente interessado, você registra o negócio na Academia.
5. O coordenador de parcerias conduz a proposta com você até a assinatura.'), 'Kits de abordagem, para disparar materiais, e Minhas propostas, para acompanhar a esteira.', 'Projetos, para enviar materiais aos clientes, e Negócios, para registrar cada atendimento.') where conteudo like '%Ficha Cadastral%' or conteudo like '%Minhas propostas%';
update public.aulas set conteudo = replace(replace(conteudo, '1. Em Kits de abordagem, escolha o lançamento e a tese.', '1. Em Projetos, abra o empreendimento e escolha a tese.'), 'Acompanhe em Meu desempenho quando o cliente abre o link.', 'Acompanhe em Meus envios quando o cliente abre o link.') where conteudo like '%Kits de abordagem%' or conteudo like '%Meu desempenho%';
update public.aulas set conteudo = replace(conteudo, 'Use o kit do Verya na área Kits de abordagem e o book completo no Google Drive.', 'Use o kit e o book do Verya na página do projeto, em Projetos.') where conteudo like '%área Kits de abordagem%';
update public.quiz_perguntas set enunciado = 'Quem conduz a proposta junto à Chaincorp quando o cliente decide?', opcoes = '["O gestor da sua imobiliária","O próprio cliente","O coordenador de parcerias, com você","O cartório"]'::jsonb, correta = 2, explicacao = 'O coordenador de parcerias conduz a proposta com o corretor até a assinatura.' where enunciado = 'Quem analisa a Ficha Cadastral depois que você envia?';

